-- ============================================================
-- Sistem Kasir Bengkel & Servis Motor - PHP Native + MySQL
-- Import lewat phpMyAdmin atau:  mysql -u root -p < database/kasir_bengkel.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS kasir_bengkel CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kasir_bengkel;

DROP TABLE IF EXISTS stok_masuk;
DROP TABLE IF EXISTS wo_item;
DROP TABLE IF EXISTS work_order;
DROP TABLE IF EXISTS kendaraan;
DROP TABLE IF EXISTS pelanggan;
DROP TABLE IF EXISTS sparepart;
DROP TABLE IF EXISTS jasa;
DROP TABLE IF EXISTS mekanik;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_bengkel VARCHAR(100) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  interval_servis_hari SMALLINT NOT NULL DEFAULT 60,
  interval_servis_km INT NOT NULL DEFAULT 2000
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','kasir') NOT NULL DEFAULT 'kasir',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE mekanik (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  telepon VARCHAR(20),
  aktif TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE pelanggan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  telepon VARCHAR(20) NOT NULL UNIQUE,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE kendaraan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  pelanggan_id INT NOT NULL,
  plat VARCHAR(15) NOT NULL UNIQUE,
  merk VARCHAR(30) NOT NULL,
  tipe VARCHAR(50) NOT NULL,
  tahun SMALLINT,
  km_terakhir INT NOT NULL DEFAULT 0,
  FOREIGN KEY (pelanggan_id) REFERENCES pelanggan(id)
) ENGINE=InnoDB;

CREATE TABLE jasa (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  tarif INT NOT NULL
) ENGINE=InnoDB;

CREATE TABLE sparepart (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  nama VARCHAR(100) NOT NULL,
  satuan VARCHAR(15) NOT NULL DEFAULT 'pcs',
  stok INT NOT NULL DEFAULT 0,
  stok_min INT NOT NULL DEFAULT 5,
  harga_beli INT NOT NULL,
  harga_jual INT NOT NULL
) ENGINE=InnoDB;

CREATE TABLE work_order (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  kendaraan_id INT NOT NULL,
  mekanik_id INT NULL,
  km INT NOT NULL DEFAULT 0,
  keluhan VARCHAR(255),
  status ENUM('antri','dikerjakan','selesai','lunas','batal') NOT NULL DEFAULT 'antri',
  total_jasa INT NOT NULL DEFAULT 0,
  total_part INT NOT NULL DEFAULT 0,
  diskon INT NOT NULL DEFAULT 0,
  total INT NOT NULL DEFAULT 0,
  bayar INT NOT NULL DEFAULT 0,
  metode ENUM('Tunai','Transfer','QRIS') NULL,
  user_id INT NULL,
  masuk_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  selesai_at DATETIME NULL,
  lunas_at DATETIME NULL,
  INDEX (status), INDEX (lunas_at),
  FOREIGN KEY (kendaraan_id) REFERENCES kendaraan(id),
  FOREIGN KEY (mekanik_id) REFERENCES mekanik(id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE wo_item (
  id INT AUTO_INCREMENT PRIMARY KEY,
  wo_id INT NOT NULL,
  jenis ENUM('jasa','part') NOT NULL,
  ref_id INT NOT NULL,
  nama VARCHAR(100) NOT NULL,
  qty INT NOT NULL DEFAULT 1,
  harga INT NOT NULL,
  harga_beli INT NOT NULL DEFAULT 0,   -- snapshot modal untuk hitung laba sparepart
  FOREIGN KEY (wo_id) REFERENCES work_order(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE stok_masuk (
  id INT AUTO_INCREMENT PRIMARY KEY,
  sparepart_id INT NOT NULL,
  qty INT NOT NULL,
  harga_beli INT NOT NULL,
  supplier VARCHAR(100),
  tanggal DATE NOT NULL,
  user_id INT NULL,
  FOREIGN KEY (sparepart_id) REFERENCES sparepart(id) ON DELETE CASCADE
) ENGINE=InnoDB;

