SET @n := 0;
UPDATE work_order SET kode = CONCAT('WO-', DATE_FORMAT(masuk_at,'%y%m%d'), '-', LPAD(@n := @n + 1, 4, '0')) ORDER BY masuk_at, id;
-- KM terakhir kendaraan mengikuti servis terakhirnya
UPDATE kendaraan k SET km_terakhir = (SELECT MAX(km) FROM work_order w WHERE w.kendaraan_id = k.id) WHERE EXISTS (SELECT 1 FROM work_order w WHERE w.kendaraan_id = k.id);
